import fs from 'node:fs/promises';
const dir='data/research/margin3-market-volume-20261107',read=async p=>JSON.parse(await fs.readFile(p)),x=await read(dir+'/results.json'),u=await read(dir+'/uncertainty.json');
const fmt=(n,d=2)=>Number.isFinite(n)?n.toFixed(d):'—',vn=t=>new Date(t).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}),names={VOLUME:'Volume ≥1,5×',FLOW:'Lực chủ động cùng hướng ≥55%',COIN_TREND:'Coin 1 giờ cùng hướng',BTC_TREND:'BTC 1 giờ cùng hướng',FLOW_VOLUME:'Volume + lực chủ động',CONFLUENCE:'Volume + lực chủ động + coin + BTC'};
